int sliding_window_max(const int arr[], int n, int k) {
    if (n < k) return -1;
    int cur = 0;
    for (int i = 0; i < k; i++) cur += arr[i];
    int max_sum = cur;
    for (int i = k; i < n; i++) {
        cur += arr[i] - arr[i - k];
        if (cur > max_sum) max_sum = cur;
    }
    return max_sum;
}

